<template>
  <el-dialog
    title="授权"
    :visible.sync="addVisible"
    width="50%"
    :close-on-click-modal="false"
    @closed="closed"
  >
    <el-form
      :model="addForm"
      ref="addForm"
      label-width="120px"
      class="mt-20"
      size="small"
    >
      <el-form-item label="设备序列号:">{{ sysInfo.serial_number }} </el-form-item>
      <el-form-item label="授权码:" prop="auth_coode">
        <el-input
          type="textarea"
          v-model="addForm.auth_coode"
          :autosize="{ minRows: 6, maxRows: 18 }"
          style="width: 80%"
        />
      </el-form-item>
    </el-form>
    <span slot="footer" class="dialog-footer">
      <el-button @click="addVisible = false">取 消</el-button>
      <el-button type="primary" @click="submitForm('addForm')">确 定</el-button>
    </span>
  </el-dialog>
</template>

<script>
export default {
  props: {
    isAuthorize: {
      type: Boolean,
    },
  },
  data() {
    return {
      addVisible: false,
      addForm: {},
      sysInfo: {},
    };
  },
  created() {
    this.addVisible = this.isAuthorize;
    this.getSysInfo();
  },
  methods: {
    getSysInfo() {
      this.$api.get(`/sys/getSysInfo`).then((res) => {
        if (res.data.data) {
          this.sysInfo = res.data.data;
        }
      });
    },
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          this.$api.post("/sys/saveSysAuth", this.addForm).then(() => {
            this.$message.success("操作成功");
            this.addVisible = false;
          });
        }
      });
    },
    closed() {
      this.$emit("close");
    },
  },
};
</script>

<style></style>
